import { getAvailableProviders, ProviderConfig } from "./providers";
import { logger } from "@/lib/logger";
import { localOcr } from "@/lib/ocr/local-ocr";
import { pythonOcr } from "@/lib/ocr/python-ocr";

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface ChatCompletionParams {
  model?: string;
  messages: ChatMessage[];
  temperature?: number;
  max_tokens?: number;
  response_format?: { type: string };
}

interface ChatCompletionChoice {
  message: { content: string };
}

export interface ChatCompletionResponse {
  choices: ChatCompletionChoice[];
}

async function callProvider(
  provider: ProviderConfig,
  params: ChatCompletionParams
): Promise<ChatCompletionResponse> {
  const apiKey = process.env[provider.apiKeyEnv];
  if (!apiKey) throw new Error(`No API key for ${provider.name}`);

  const body = {
    model: provider.model,
    messages: params.messages,
    ...(params.temperature !== undefined && { temperature: params.temperature }),
    ...(params.max_tokens !== undefined && { max_tokens: params.max_tokens }),
    ...(params.response_format && { response_format: params.response_format }),
  };

  const res = await fetch(`${provider.baseURL}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
      ...provider.headers,
    },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(30000),
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`${provider.name} returned ${res.status}: ${text.slice(0, 200)}`);
  }

  return res.json();
}

export interface GeminiVisionResponse {
  candidates?: {
    content?: {
      parts?: { text?: string }[];
    };
  }[];
}

export async function callGeminiVision(
  imageBuffer: ArrayBuffer,
  prompt: string
): Promise<string> {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) throw new Error("GEMINI_API_KEY is not configured");

  const base64 = bufferToBase64(imageBuffer);
  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`;

  const body = {
    contents: [
      {
        parts: [
          { text: prompt },
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64,
            },
          },
        ],
      },
    ],
    generationConfig: {
      temperature: 0.1,
      maxOutputTokens: 4000,
      responseMimeType: "application/json",
    },
  };

  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(60000),
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Gemini Vision returned ${res.status}: ${text.slice(0, 300)}`);
  }

  const data = (await res.json()) as GeminiVisionResponse;
  const text = data.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("Gemini Vision returned empty content");
  return text;
}

function bufferToBase64(buffer: ArrayBuffer): string {
  return Buffer.from(buffer).toString("base64");
}

const FREE_VISION_MODELS = [
  // Best free models for OCR / text extraction
  "google/gemma-4-26b-a4b-it:free",
  "google/gemma-4-31b-it:free",
  "nvidia/nemotron-3-nano-omni-30b-a3b-reasoning:free",
  "nvidia/nemotron-nano-12b-v2-vl:free",
  "nvidia/nemotron-3.5-content-safety:free",
  "openrouter/free",
] as const;

async function callOpenRouterVisionModel(
  imageBuffer: ArrayBuffer,
  prompt: string,
  model: string,
  timeoutMs: number = 90000
): Promise<string> {
  const apiKey = process.env.OPENROUTER_API_KEY;
  if (!apiKey) throw new Error("OPENROUTER_API_KEY is not configured");

  const base64 = bufferToBase64(imageBuffer);

  const res = await fetch("https://openrouter.ai/api/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
      "HTTP-Referer": "https://menulens.app",
      "X-Title": "MenuLens",
    },
    body: JSON.stringify({
      model,
      messages: [
        {
          role: "user",
          content: [
            { type: "text", text: prompt },
            {
              type: "image_url",
              image_url: {
                url: `data:image/jpeg;base64,${base64}`,
              },
            },
          ],
        },
      ],
      temperature: 0.1,
      max_tokens: 4096,
    }),
    signal: AbortSignal.timeout(timeoutMs),
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`${model} returned ${res.status}: ${text.slice(0, 300)}`);
  }

  const data = await res.json();
  const content = data.choices?.[0]?.message?.content;
  if (!content) throw new Error(`${model} returned empty content`);
  return content;
}

export async function callVisionOCR(
  imageBuffer: ArrayBuffer,
  prompt: string
): Promise<string> {
  const errors: string[] = [];

  // Try free OpenRouter models in order (Gemma 4, Nemotron, Lyria, router)
  if (process.env.OPENROUTER_API_KEY) {
    for (const model of FREE_VISION_MODELS) {
      try {
        logger.info({ message: "Trying vision model", model });
        return await callOpenRouterVisionModel(imageBuffer, prompt, model);
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        errors.push(`${model}: ${msg}`);
        logger.warn({ message: `Vision model ${model} failed`, error: msg });
      }
    }
  }

  // Fallback to Gemini Vision (free tier)
  if (process.env.GEMINI_API_KEY) {
    try {
      return await callGeminiVision(imageBuffer, prompt);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push(`Gemini: ${msg}`);
    }
  }

  // Final fallback: local offline OCR via Tesseract.js — no API key, no rate limits
  try {
    logger.info({ message: "Trying local Tesseract OCR fallback" });
    const result = await localOcr(imageBuffer);
    if (result && result.length > 10) {
      return result;
    }
    throw new Error("LocalOCR result too short");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    errors.push(`LocalOCR: ${msg}`);
  }

  // Ultimate fallback: Python/pytesseract subprocess
  try {
    logger.info({ message: "Trying Python OCR fallback" });
    const result = await pythonOcr(imageBuffer);
    if (result && result.length > 10) {
      return result;
    }
    throw new Error("PythonOCR result too short");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    errors.push(`PythonOCR: ${msg}`);
  }

  // Build a user-friendly error message
  const isRateLimit = errors.some((e) => e.includes("429") || e.includes("quota") || e.includes("rate limit"));
  const hasGemini = !!process.env.GEMINI_API_KEY;
  let userMessage: string;
  if (isRateLimit && !hasGemini) {
    userMessage = "All AI vision models are currently rate-limited due to daily free tier limits. They reset at midnight UTC. Please try again tomorrow, or add a Gemini API key to bypass OpenRouter rate limits.";
  } else if (isRateLimit && hasGemini) {
    userMessage = "All AI vision models failed. The Gemini fallback also failed — check that your Gemini API key is valid and has quota remaining. OpenRouter free models are rate-limited until midnight UTC.";
  } else {
    userMessage = `All vision providers failed. ${errors.join("; ")}`;
  }

  throw new Error(userMessage);
}

export async function chatCompletions(
  params: ChatCompletionParams
): Promise<ChatCompletionResponse> {
  const available = getAvailableProviders();

  if (available.length === 0) {
    throw new Error("No AI providers configured. Add at least one API key to .env.local");
  }

  let lastError: Error | null = null;

  for (const provider of available) {
    try {
      const result = await callProvider(provider, params);
      const content = result?.choices?.[0]?.message?.content;
      if (!content) {
        throw new Error(`${provider.name} returned empty content`);
      }
      return result;
    } catch (err) {
      lastError = err instanceof Error ? err : new Error(String(err));
      logger.warn(`AI provider ${provider.name} failed: ${lastError.message}`);
    }
  }

  throw new Error(
    `All AI providers failed. Last error: ${lastError?.message || "unknown"}`
  );
}
