import { logger } from "@/lib/logger";

/**
 * Local OCR placeholder — Tesseract.js worker has path conflicts with Next.js.
 * The Python subprocess OCR (python-ocr.ts) handles the offline fallback instead.
 */
export async function localOcr(imageBuffer: ArrayBuffer): Promise<string> {
  void imageBuffer; // unused — Tesseract.js has Next.js bundling conflicts
  logger.warn("[LocalOCR] Tesseract.js not available in Next.js — falling through to Python OCR");
  throw new Error("Tesseract.js unavailable in Next.js context");
}
